import { defineConfig, mergeConfig } from 'vitest/config';
import nodeSharedConfig from '../../../../vitest.shared';
import domSharedConfig from '../../../../vitest.dom.shared';

// Dual preset — this package has logic specs that vi.mock('@angular/core') or
// vi.mock('@memberjunction/core'); those mocks break under the Angular AOT compile path, so
// they stay on the fast node preset while *.dom.test.ts run under the jsdom/Angular DOM
// preset. The two projects are kept disjoint by EXCLUSION (mergeConfig concatenates the
// include/exclude arrays). Generated by scripts/gen-dom-stub.mjs. See
// guides/ANGULAR_TESTING_GUIDE.md §3b.
// M5 joined workspace: packages installed in the parent .pnpm store (M5) vs the
// nested repo .pnpm store (MJ) can resolve @angular/* from two physical paths
// (e.g. angular-split in MJ/node_modules/.pnpm vs @angular/core in M5/node_modules/.pnpm),
// causing NG0203 when SplitComponent calls inject() against a different @angular/core copy.
// Deduplicating and inlining @angular/* + angular-split forces Vite to serve one canonical
// instance across both standalone checkouts and nested joined workspaces.
const ANGULAR_DEDUPE_DEPS = [
  '@angular/animations',
  '@angular/cdk',
  '@angular/common',
  '@angular/compiler',
  '@angular/core',
  '@angular/forms',
  '@angular/platform-browser',
  '@angular/router',
];

const DOM_INLINE_DEPS = [...ANGULAR_DEDUPE_DEPS, 'angular-split'];

export default defineConfig({
  test: {
    projects: [
      mergeConfig(
        nodeSharedConfig,
        defineConfig({
          test: {
            name: 'explorer-core (node)',
            environment: 'node',
            include: ['src/**/__tests__/**/*.spec.ts'],
            exclude: ['**/*.dom.test.ts'],
          },
        }),
      ),
      mergeConfig(
        domSharedConfig,
        defineConfig({
          resolve: { dedupe: ANGULAR_DEDUPE_DEPS },
          // The dom shared config contributes a broad `src/**/*.test.ts` include; exclude every
          // non-`.dom` test so node-only logic specs that live OUTSIDE __tests__ (e.g.
          // dashboard-resource.component.test.ts, which vi.mocks @angular/core) don't get pulled
          // through the Angular AOT path. `!(*.dom)` keeps *.dom.test.ts while dropping the rest.
          test: {
            name: 'explorer-core (dom)',
            include: ['src/**/*.dom.test.ts'],
            exclude: ['**/__tests__/**', '**/!(*.dom).test.ts'],
            server: { deps: { inline: DOM_INLINE_DEPS } },
          },
        }),
      ),
    ],
  },
});
